INSERT OR IGNORE INTO merchant_qa(qa_id,merchant_id,user_id,question,answer,answered_by,created_at) VALUES ('qa_factory_invoice','mer_7a4c19d2','user_seed_tb_013','Can you issue a company invoice and provide a no-photography notice?','A company invoice is available; the route includes a customer prototype area, so a photography-boundary acknowledgement is required.','merchant','2026-07-07T09:00:00Z');
INSERT OR IGNORE INTO merchant_qa(qa_id,merchant_id,user_id,question,answer,answered_by,created_at) VALUES ('qa_factory_refund','mer_7a4c19d2','user_seed_tb_013','By what time can a reserved place be cancelled without penalty?','Cancellation up to three business days before the visit is free and the deposit is returned; later cancellation forfeits half the deposit.','merchant','2026-07-08T02:00:00Z');
INSERT OR IGNORE INTO merchant_qa(qa_id,merchant_id,user_id,question,answer,answered_by,created_at) VALUES ('qa_lunch_refund','mer_5e91a7c3','user_seed_tb_013','How is settlement handled when the headcount falls?','Settle by actual attendance, but not below 90% of the contracted count; report reductions by 10:00 that day.','merchant','2026-07-08T02:15:00Z');
